package com.kashibanaras.ecommerce.controller; import com.kashibanaras.ecommerce.dto.ApiResponse; import com.kashibanaras.ecommerce.entity.Category; import com.kashibanaras.ecommerce.repository.CategoryRepository; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/categories") public class CategoryController{private final CategoryRepository r;public CategoryController(CategoryRepository r){this.r=r;}@GetMapping public ApiResponse<List<Category>> all(){return ApiResponse.success("Categories",r.findAll().stream().filter(Category::isActive).toList());}}
